const upsertCustomer = `-- name: UpsertCustomer :one
INSERT INTO customers (brand_id, name, wa_number_e164, first_order_at, last_order_at, orders_count)
VALUES ($1, $2, $3, now(), now(), 1)
ON CONFLICT (brand_id, wa_number_e164) DO UPDATE
SET name = EXCLUDED.name,
    last_order_at = now(),
    orders_count = customers.orders_count + 1
RETURNING id, brand_id, name, wa_number_e164, first_order_at, last_order_at, orders_count, total_spent
`

type UpsertCustomerParams struct {
	BrandID      uuid.UUID
	Name         string
	WaNumberE164 string
}

func (q *Queries) UpsertCustomer(ctx context.Context, arg UpsertCustomerParams) (Customer, error) {
	row := q.db.QueryRow(ctx, upsertCustomer, arg.BrandID, arg.Name, arg.WaNumberE164)
	var i Customer
	err := row.Scan(
		&i.ID,
		&i.BrandID,
		&i.Name,
		&i.WaNumberE164,
		&i.FirstOrderAt,
		&i.LastOrderAt,
		&i.OrdersCount,
		&i.TotalSpent,
	)
	return i, err
}
